id":"D3-handover-2","category":"철거작업","source":"manual","measure":"","factor":"해체 진행·자재 반출·균열·예상 외 배선·중지 조치 누락으로 작업 상태·해제 조건 오인","current_measure":"해체 진행·자재 반출·균열·예상 외 배선·중지 조치을 실제 확인 결과와 담당자·시각·근거 문서 번호에 연결해 기록한다.","recommend_measure":"기록과 현장 상태가 다르면 다음 단계 진행을 보류한다. 변경 사항·조치 담당·재확인 결과를 남긴 뒤 지정 권한자가 진행 여부를 판단한다."}],"severity":null,"frequency":null,"riskLevel":null,"customFields":{}},{"id":3,"proc":{"stepTitle":"잔재 확인과 인계 · 기록 확인","stepDetail":"돌출 못·날카로운 절단부·폐기물·바닥 손상을 정리한다. 기록 항목: 잔존 구조·개구부·폐기물·격리 유지와 구역 인계."},"risks":[{"id":"risk-1790786613956-rruy0h1dz","factor":"찔림·베임, 잔존 부재 붕괴, 통로 걸림","source":"manual","measure":"","category":"폐기물처리","current_measure":"폐기물을 분리하고 안전한 반출 경로를 유지한다.","recommend_measure":"책임자가 잔존 구조·개구부·격리 상태를 확인한 뒤 차단시설을 해제한다."},{"id":"D3-handover-3","category":"폐기물처리","source":"manual","measure":"","factor":"잔존 구조·개구부·폐기물·격리 유지와 구역 인계 누락으로 작업 상태·해제 조건 오인","current_measure":"잔존 구조·개구부·폐기물·격리 유지와 구역 인계을 실제 확인 결과와 담당자·시각·근거 문서 번호에 연결해 기록한다.","recommend_measure":"인계자와 인수자가 미결 사항·사용 제한·후속 조치 담당을 함께 확인한다. 확인되지 않은 항목은 완료로 처리하지 않는다."}],"severity":null,"frequency":null,"riskLevel":null,"customFields":{}}]}]$payload$::jsonb) as x(original_title text,expected_updated_at timestamptz,base text,basic jsonb,technical jsonb,handover jsonb);
do $$ begin
 if (select count(*) from public.jsa_projects p join operator_content_payload d on d.original_title=p.title and p.updated_at=d.expected_updated_at where p.is_public )<>12 then raise exception 'SOURCE_CONTENT_CHANGED'; end if;
end $$;
insert into jsa_private.operator_seed_backup(project_id,snapshot)
 select p.id,to_jsonb(p) from public.jsa_projects p join operator_content_payload d on p.title=d.original_title;
alter table public.jsa_projects disable trigger phase6_project_owner;
update public.jsa_projects p set
 author_id=u.id,user_id=u.id,title=d.base,project_name=d.base,
 form_data=jsonb_set(p.form_data,'{projectName}',to_jsonb(d.base)),
 analysis_data=d.basic,
 custom_layout=jsonb_set(p.custom_layout,'{docTitle}',to_jsonb(d.base||' 위험성평가')),
 document_group_id=p.id,document_variant='basic',
 publication_context=jsonb_build_object('scope',d.base||'의 기본 작업통제. 단계별 위험요인과 현재 안전대책·감소권고대책을 정리합니다.','region','대한민국','limitations','현장 측정·검사·승인 기록이 아닌 작성 참고자료입니다. 실제 조건을 확인하고 가능성·중대성·위험성을 현장에서 평가하여 작성합니다.','sources','기존 공개 JSA의 작업 범위와 통제 내용을 바탕으로 재구성. 장비 제조사 지침·SDS·현장 작업허가 및 승인 절차를 대상별로 확인합니다.'),
 updated_at=now()
from operator_content_payload d,auth.users u
where p.title=d.original_title and u.id=(select user_id from public.operator_accounts);
alter table public.jsa_projects enable trigger phase6_project_owner;
insert into public.jsa_projects(author_id,user_id,title,project_name,is_public,form_data,participants,analysis_data,custom_layout,tags,auto_tags,public_locale,public_country,reuse_license,publication_context,document_group_id,document_variant)
select p.author_id,p.user_id,d.base||' · '||variant.label,d.base,true,p.form_data,'[]'::jsonb,
 case variant.kind when 'technical' then d.technical else d.handover end,
 p.custom_layout,p.tags,p.auto_tags,p.public_locale,p.public_country,p.reuse_license,
 p.publication_context||jsonb_build_object('scope',d.base||'의 '||variant.label||' 버전. '||case variant.kind when 'technical' then '장비·재료·격리·방호의 결함과 기능 확인 및 중지 조건을 중심으로 정리합니다.' else '단계별 근거 기록·담당자·미결 사항·인수 조건을 중심으로 정리합니다.' end),
 p.id,variant.kind
from public.jsa_projects p join operator_content_payload d on p.title=d.base
cross join (values('technical','기술 실패'),('handover','기록 인계')) variant(kind,label)
where p.document_variant='basic' and p.document_group_id=p.id and exists(select 1 from jsa_private.operator_seed_backup b where b.project_id=p.id);
do $$ begin
 if (select count(*) from public.jsa_projects p join jsa_private.operator_seed_backup b on b.project_id=p.document_group_id)<>36 then raise exception 'VARIANT_COUNT_MISMATCH'; end if;
 if exists(select 1 from public.jsa_projects p join jsa_private.operator_seed_backup b on b.project_id=p.document_group_id cross join lateral jsonb_array_elements(p.analysis_data) s where (s->>'frequency') is not null or (s->>'severity') is not null or (s->>'riskLevel') is not null) then raise exception 'RISK_NOT_BLANK'; end if;
end $$;
